class TokenCache:
    def __init__(self, fetch, clock, margin=30):
        self.fetch = fetch
        self.clock = clock
        self.margin = margin
        self._token = None
        self._expiry = 0

    def token(self):
        if self._token is not None and self.clock() < self._expiry - self.margin:
            return self._token
        data = self.fetch()
        token = data.get("access_token") if isinstance(data, dict) else None
        lifetime = data.get("expires_in") if isinstance(data, dict) else None
        if not isinstance(token, str) or not token:
            raise ValueError("token response has no access_token")
        if not isinstance(lifetime, int) or isinstance(lifetime, bool) or lifetime <= 0:
            raise ValueError("token response has no valid expires_in")
        self._token = token
        self._expiry = self.clock() + lifetime
        return token

    def invalidate(self):
        self._token = None

    def call(self, send):
        result = send(self.token())
        if result[0] == 401:
            self.invalidate()
            result = send(self.token())
        return result

