class Clock:
    def __init__(self, t=1000):
        self.t = t
    def __call__(self):
        return self.t

class Issuer:
    def __init__(self, lifetime=3600):
        self.count = 0
        self.lifetime = lifetime
    def __call__(self):
        self.count += 1
        return {"access_token": f"tok{self.count}", "expires_in": self.lifetime, "token_type": "Bearer"}

@test("one fetch while the token is fresh")
def _():
    clock, issuer = Clock(), Issuer()
    cache = TokenCache(issuer, clock)
    check_eq(cache.token(), "tok1")
    clock.t = 1000 + 3600 - 31
    check_eq(cache.token(), "tok1")
    check_eq(issuer.count, 1)

@test("renewing before expiry")
def _():
    clock, issuer = Clock(), Issuer()
    cache = TokenCache(issuer, clock)
    cache.token()
    clock.t = 1000 + 3600 - 30
    check_eq(cache.token(), "tok2")
    clock.t += 3000
    check_eq(cache.token(), "tok2")
    clock.t += 600
    check_eq(cache.token(), "tok3")
    check_eq(issuer.count, 3)

@test("a different margin")
def _():
    clock, issuer = Clock(0), Issuer(100)
    cache = TokenCache(issuer, clock, margin=0)
    cache.token()
    clock.t = 99
    check_eq(cache.token(), "tok1")
    clock.t = 100
    check_eq(cache.token(), "tok2")

@test("invalidating")
def _():
    clock, issuer = Clock(), Issuer()
    cache = TokenCache(issuer, clock)
    cache.token()
    cache.invalidate()
    check_eq(cache.token(), "tok2")

@test("retrying once after a 401")
def _():
    clock, issuer = Clock(), Issuer()
    cache = TokenCache(issuer, clock)
    seen = []
    def send(token):
        seen.append(token)
        return (401, "expired") if token == "tok1" else (200, "ok")
    check_eq(cache.call(send), (200, "ok"))
    check_eq(seen, ["tok1", "tok2"])
    check_eq(cache.call(send), (200, "ok"))
    check_eq(seen, ["tok1", "tok2", "tok2"])

@test("only once")
def _():
    clock, issuer = Clock(), Issuer()
    cache = TokenCache(issuer, clock)
    seen = []
    def always_401(token):
        seen.append(token)
        return (401, "no")
    check_eq(cache.call(always_401), (401, "no"))
    check_eq(seen, ["tok1", "tok2"])
    check_eq(cache.call(lambda t: (403, "forbidden")), (403, "forbidden"))
    check_eq(issuer.count, 2)

@test("broken token responses")
def _():
    clock = Clock()
    check_raises(ValueError, TokenCache(lambda: {"expires_in": 60}, clock).token)
    check_raises(ValueError, TokenCache(lambda: {"access_token": "", "expires_in": 60}, clock).token)
    check_raises(ValueError, TokenCache(lambda: {"access_token": "t", "expires_in": "60"}, clock).token)
    check_raises(ValueError, TokenCache(lambda: {"access_token": "t", "expires_in": 0}, clock).token)
    check_raises(ValueError, TokenCache(lambda: {"access_token": "t"}, clock).token)

